const TOPICS = [
  {id:'em_scenekunst_teaterinstitusjon_repertoar',chapter:'institusjon-historie-produksjonsfelt',sources:['src_sceneweb','src_kult_stats'],title:'Teaterinstitusjon og repertoar',paragraphs:[
    'En sceneinstitusjon må analyseres som en kjede av forskjellige beslutninger: mandat og organisering setter rammer, programmering velger konkrete produksjoner, og faktisk aktivitet kan undersøkes gjennom repertoar- og arrangementsdata. Sceneweb skiller mellom produksjoner, organisasjoner og spillesteder, mens Kulturdirektoratets statistikk skiller aktivitet, publikum og økonomi. Det gjør det metodisk uforsvarlig å bruke institusjonens egen formålsbeskrivelse som direkte bevis for hva som faktisk ble spilt eller hvem som møtte opp.',
    'Repertoar er et tidsordnet utvalg, ikke bare en liste over titler. For å undersøke kontinuitet og endring må analysen registrere produksjon, premiere eller spilleperiode, kunstneriske krediteringer, arena og eventuell gjenopptakelse før den sammenligner sesonger. Sceneweb er nyttig nettopp fordi produksjon, organisasjon og spillested er separate objekter; sammenstillingen må likevel kontrolleres mot institusjonens egne program- eller årsdata når konklusjonen gjelder en bestemt sesong.',
    'Institusjonell synlighet sier heller ikke i seg selv noe om kunstnerisk kvalitet. Kulturdirektoratets tall kan dokumentere offentlig støtte, arrangement, besøk, egeninntekter og lønnskostnader, men disse variablene må holdes adskilt fra estetisk vurdering. En universitetsnær institusjonsanalyse forklarer derfor hvilke ressurser og porter som former repertoaret, samtidig som den reserverer kvalitetsdommen for selvstendig forestillings- og resepsjonsanalyse.'
  ]},
  {id:'em_scenekunst_scenekunsthistorie_tradisjoner_brudd',chapter:'institusjon-historie-produksjonsfelt',sources:['src_sceneweb','src_sceneweb_nb','src_ntnu_learning'],title:'Scenekunsthistorie, tradisjoner og brudd',paragraphs:[
    'Scenekunsthistorie rekonstruerer hendelser som ikke lenger finnes i sin opprinnelige live-form. Sceneweb beskriver materiale fra 1635 og framover, men understreker samtidig at databasen ikke er et fullstendig arkiv. Historisk kildekritikk må derfor begynne med proveniens og bevaringssituasjon: et program dokumenterer at en produksjon ble presentert på en bestemt måte, mens et foto fryser ett utsnitt og en senere omtale kan være formet av ettertidens begreper.',
    'Begrepene tradisjon og brudd krever sammenligning over tid. NTNUs drama- og teaterstudium gjør kjennskap til fagets tradisjoner og brudd til en del av læringsutbyttet, men et historisk brudd kan ikke bevises ved at én produksjon kaller seg ny. Analysen må vise hvilke konvensjoner som faktisk videreføres eller endres i dramaturgi, utøverpraksis, organisering, teknologi eller publikumssituasjon, og den må velge et tidsrom som gjør sammenligningen meningsfull.',
    'Nasjonalbibliotekets programsamling i Sceneweb illustrerer hvordan én kildetype kan gi bred kronologisk dekning uten å gi full tilgang til selve forestillingen. Programmet kan dokumentere krediteringer, repertoar, institusjonell språkbruk og noen ganger kunstnerisk intensjon, men det kan ikke alene rekonstruere tempo, stemmebruk, lysforløp eller publikumsrespons. Derfor skal historisk argumentasjon markere eksplisitt når den går fra dokumentert spor til sannsynlig tolkning.'
  ]},
  {id:'em_scenekunst_produksjon_arbeid_finansiering',chapter:'institusjon-historie-produksjonsfelt',sources:['src_kult_stats','src_kult_funding','src_khio_choreo'],title:'Produksjon, arbeid, økonomi og kulturpolitikk',paragraphs:[
    'Produksjonsanalyse undersøker hvordan tid, arbeidsdeling, økonomi, kunstneriske valg og tekniske ressurser kobles sammen. Kulturdirektoratet skiller mellom ordninger for produksjon, arrangører, etablerte virksomheter og kunstnerskap, noe som viser at finansiering kan rette seg mot ulike ledd i verdikjeden. En analyse må derfor navngi hvilken ressurs eller ordning som undersøkes, og kan ikke behandle «støtte» som én homogen årsak til et kunstnerisk resultat.',
    'Sektorstatistikk kan beskrive økonomiske rammer gjennom blant annet egeninntekter, lønnskostnader og offentlige tilskudd. Slike tall er viktige for å forstå kapasitet og risiko, men de beviser verken effektiv ledelse eller høy kunstnerisk kvalitet. Dersom et årsresultat endres, må analysen undersøke regnskapsmessige og organisatoriske forklaringer før den tilskriver endringen repertoar, publikum eller kunstneriske valg.',
    'Scenekunst er kollektivt arbeid, og KHiOs koreografimaster fremhever både tverrfaglig samarbeid, ansvarlig kunstnerisk ledelse og yrkesetiske problemstillinger. Det gjør kreditering og prosesskilder faglig viktige: sluttforestillingen kan vise at et valg finnes, men ikke nødvendigvis hvem som foreslo det, hvilke alternativer som ble forkastet eller hvordan makt var fordelt i prøverommet. Produksjonsanalysen må derfor skille resultat, prosess og etterfølgende selvforklaring.'
  ]},
  {id:'em_scenekunst_turne_festival_infrastruktur',chapter:'institusjon-historie-produksjonsfelt',sources:['src_kult_tour','src_kult_stats'],title:'Turné, festival og infrastruktur',paragraphs:[
    'Turné er mer enn transport av et ferdig verk. Kulturdirektoratets gjestespill- og turnéordning skiller eksplisitt mellom visninger etter premiere, gjenopptakelse og selve produksjonen. For scenekunstanalysen betyr det at en turnéversjon kan kreve nye prøver, andre tekniske løsninger, endret scenografi eller lokal tilpasning. Sammenligning må derfor registrere spillested, sceneformat, teknisk rider og produksjonsversjon i stedet for å anta at alle visninger er identiske.',
    'Festivaler og gjestespill er distribusjonsinfrastruktur fordi de bestemmer når, hvor og for hvilke publikum en produksjon kan møte offentligheten. Kulturdirektoratets statistikk registrerer arrangement og turné som egne aktivitetsmål. Tallene kan beskrive geografisk sirkulasjon og aktivitetsnivå, men de sier ikke alene om nye publikumsgrupper faktisk ble nådd eller hvordan verket ble mottatt på hvert sted.',
    'Infrastruktur former også kunstneriske muligheter gjennom tilgjengelig scene, riggetid, reisebudsjett, lagring og personell. En robust turnéanalyse kobler slike produksjonsbetingelser til dokumenterte endringer i forestillingen og unngår teknologisk determinisme: et mindre rom kan utløse en annen løsning, men det må dokumenteres før rommet brukes som årsaksforklaring. Dermed blir distribusjon en empirisk del av verkets livsløp, ikke en logistisk fotnote.'
  ]},
  {id:'em_scenekunst_arkiv_dokumentasjon_rekonstruksjon',chapter:'institusjon-historie-produksjonsfelt',sources:['src_sceneweb','src_sceneweb_nb','src_khio_choreo'],title:'Arkiv, dokumentasjon og rekonstruksjon',paragraphs:[
    'Scenekunstarkivet består av heterogene spor: programmer, fotografier, videoer, anmeldelser, plakater, manus, regibøker og organisatoriske dokumenter bærer forskjellig informasjon. Sceneweb beskriver nettopp slike hybridarkiver og tar uttrykkelig forbehold om feil og mangler. Arkivanalyse må derfor registrere kildetype, opphav, datering og hva kilden ikke kan vise før materialet brukes til å rekonstruere en tidligere forestilling.',
    'Et opptak erstatter ikke den opprinnelige live-situasjonen. Kameraets utsnitt, mikrofonplassering, klipp eller komprimering kan endre forholdet mellom rom, lyd, blikk og publikum. Nasjonalbibliotekets programsamling viser den motsatte begrensningen: programmet kan bevare krediteringer og samtidige beskrivelser uten å bevare selve forløpet. Rekonstruksjon blir derfor sterkest når uavhengige kildetyper peker i samme retning og usikkerheten beholdes synlig.',
    'Dokumentasjon er også en del av dagens kunstneriske praksis. KHiOs koreografimaster legger vekt på skriftlig refleksjon og dokumentasjon, men et refleksjonsdokument er fortsatt produsert av en deltaker med et bestemt formål. Forskeren må skille samtidige arbeidsnotater fra senere retrospektive fortellinger og aldri gjøre fravær i arkivet til automatisk bevis for at en handling, person eller praksis ikke fantes.'
  ]},
  {id:'em_scenekunst_dramaturgi_iscenesettelse',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_ntnu_learning','src_ntnu_master'],title:'Dramaturgi og iscenesettelse',paragraphs:[
    'Dramaturgi beskriver hvordan en forestilling organiserer tid, oppmerksomhet og forventning, ikke bare hvordan et manus fordeler handling i akter. NTNU fremhever nyere dramaturgiske og interaktive former, og masteren i anvendt teater og dramaturgi kombinerer teoretisk og erfaringsbasert kunnskap. Analysen må derfor kunne håndtere episodiske, sirkulære, dokumentariske og publikumsresponsive forløp ved å beskrive konkrete sekvenser, overganger, gjentakelser og informasjonsfordeling.',
    'Iscenesettelse oppstår gjennom samvirket mellom tekst eller annet materiale, utøver, rom, lyd, lys, objekt og publikumssituasjon. Det betyr at samme tekst kan få ulik dramaturgisk funksjon i forskjellige produksjoner. En etterprøvbar analyse peker på observerbare valg og deres plass i forløpet før den tolker funksjon; påstander om intensjon krever prosesskilder eller eksplisitte kunstneruttalelser og kan ikke utledes sikkert fra sluttresultatet alene.',
    'Dramaturgisk forklaring bør også skille struktur fra effekt. At en forestilling bryter den fjerde veggen eller gjentar en sekvens er observerbart; at dette nødvendigvis skaper uro, nærhet eller kritisk refleksjon hos publikum er en resepsjonspåstand som krever andre data. Denne skillet mellom form, mulig funksjon og dokumentert mottakelse hindrer at forestillingsanalysen smugler inn publikumspsykologi som om den var direkte synlig på scenen.'
  ]},
  {id:'em_scenekunst_skuespill_rollefortolkning',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_khio_theatre','src_ntnu_learning'],title:'Skuespill, rollefortolkning og ensemble',paragraphs:[
    'Utøveranalyse begynner med det som kan observeres: kroppsholdning, bevegelsesbane, stemmekvalitet, tempo, timing, blikk, handling og relasjon til andre. KHiOs teaterutdanning skiller skuespill som egen profesjonspraksis innen et felt som også rommer regi, scenetekst og dramaturgi. Det er en påminnelse om at rollefortolkning ikke bør reduseres til regissørens idé eller tekstens figur; utøverens konkrete sceniske arbeid må beskrives som et eget analytisk lag.',
    'Ensemblet endrer hva en individuell prestasjon betyr. Pauser, rytme, respons og romlig avstand skapes relasjonelt, og samme handling kan få forskjellig funksjon når medutøvernes timing endres. NTNUs læringsutbytte fremhever bruk av scenekunstens virkemidler både individuelt og i samarbeid. Derfor bør analysen sammenligne sekvenser og relasjoner fremfor å rangere enkeltutøvere ut fra løsrevne øyeblikk.',
    'Indre motivasjon er en fortolkning, ikke et direkte observerbart faktum. Et intervju kan dokumentere hvordan en skuespiller beskriver sin egen prosess, men etterforklaringen må holdes adskilt fra samtidige prøve- og forestillingsspor. Universitetstilpasset rolleanalyse kan diskutere psykologiske, fysiske eller performative tradisjoner, men den må navngi hvilke tegn og kilder som bærer konklusjonen og unngå å gjøre én skuespillmetode universell.'
  ]},
  {id:'em_scenekunst_regi_scenografi',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_khio_theatre','src_khio_choreo'],title:'Regi og scenisk komposisjon',paragraphs:[
    'Regi kan forstås som samordning av utøvere, dramaturgi, rom, lyd, lys, objekter og tempo, men sluttproduktet dokumenterer ikke automatisk hvem som eide hvert valg. KHiOs teaterfelt plasserer regi ved siden av skuespill, scenetekst og dramaturgi, mens koreografimasteren understreker tverrfaglig samarbeid. En presis regianalyse skiller derfor regikonsept, dokumentert instruksjon og kollektivt utviklet materiale.',
    'Scenisk komposisjon må beskrives på flere skalaer. På mikronivå kan analysen følge en cue, en inngang eller et blikk; på sekvensnivå undersøkes rytme og overganger; på helhetsnivå vurderes hvordan motiv, rom og forløp organiseres. Det er først når disse nivåene kobles til dokumentasjon fra forestilling eller prøveprosess at analysen kan argumentere for en konsekvent registrategi fremfor å tilskrive tilfeldige likheter én styrende idé.',
    'Auteurbegrepet er derfor en hypotese om kunstnerisk organisering, ikke en standardforklaring. I kollektiv scenekunst kan scenograf, dramaturg, komponist, utøver eller teknisk team ha selvstendige beslutningsrom. Krediteringer og prosessmateriale bør brukes til å kartlegge ansvar, mens estetisk sammenheng analyseres i selve forestillingen. Slik unngås både å usynliggjøre samarbeid og å gjøre kreditering til bevis for faktisk innflytelse i hvert enkelt valg.'
  ]},
  {id:'em_scenekunst_scenetekst_adaptasjon_devising',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_khio_theatre','src_ntnu_master'],title:'Scenetekst, adaptasjon og devising',paragraphs:[
    'Scenetekst kan være dramatisk manus, dokumentarisk materiale, libretto, muntlig tekst eller tekst utviklet under prøver. KHiOs teaterportefølje behandler scenetekst og dramaturgi som egne faglige praksiser, mens NTNUs master vektlegger kritisk arbeid med teaterformer og prosjektutvikling. Analysen bør derfor kartlegge hvilke tekstversjoner som finnes, hvem som har produsert dem og hvordan de faktisk brukes i den realiserte forestillingen.',
    'Adaptasjonsanalyse sammenligner ikke bare original og sluttmanus. Utelatelser, omplasseringer, nye scener, oversettelse, rollefordeling og ikke-verbale grep kan endre kildematerialets funksjon. En sterk analyse fører en eksplisitt versjonskjede og skiller tekstlig endring fra scenisk realisering; et kutt i manus forklarer ikke alene hvordan rytme, kropp eller rom gjør endringen merkbar for publikum.',
    'Devising gjør kildeproblemet særlig tydelig fordi materiale kan oppstå gjennom improvisasjon og kollektiv utvikling. Sluttforestillingen kan dokumentere hva som ble beholdt, men ikke hvem som foreslo et grep eller når det oppstod. Prøvedagbok, arbeidsvideo og versjonshistorikk blir derfor sentrale kilder. Deltakernes senere intervjuer er verdifulle, men skal merkes som retrospektive beskrivelser og kontrolleres mot samtidige spor når eierskap eller prosess er analytisk viktig.'
  ]},
  {id:'em_scenekunst_regi_proveprosess_samarbeid',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_ntnu_learning','src_khio_choreo'],title:'Regi, prøveprosess og samarbeid',paragraphs:[
    'Prøveprosessen er en serie beslutninger og revisjoner, ikke et usynlig mellomrom mellom idé og premiere. NTNU kombinerer praktiske øvinger, workshops og produksjon med kritisk refleksjon, og KHiOs koreografimaster legger vekt på dialogbasert læring og prosjektsamarbeid. En prosessanalyse etablerer derfor tidslinje, dokumenterer endringer mellom versjoner og knytter dem til konkrete arbeidskilder før den forklarer hvordan et scenisk valg utviklet seg.',
    'Samarbeid kan ikke måles bare gjennom antall krediterte personer. Det analytiske spørsmålet er hvilke beslutningsrom, tilbakemeldingssløyfer og former for ansvar som faktisk kan dokumenteres. Prøvenotater kan vise hvem som foreslo en endring; video kan vise at den ble prøvd; sluttforestillingen kan vise om den overlevde. Når kildene ikke finnes, skal analysen beskrive resultatet uten å konstruere en sikker opprinnelseshistorie.',
    'Prøver inneholder også mislykkede eller forkastede alternativer som sluttproduktet skjuler. Det gjør prosessmateriale viktig for å forstå kunstnerisk problemløsning, men ikke automatisk mer sannferdig enn forestillingen. Deltakere kan ha ulike minner og interesser. Kildekritikken bør derfor skille samtidige spor, senere refleksjon og forskerens egen observasjon og vise hvilke av disse som bærer hver påstand om samarbeid, konflikt eller regimessig styring.'
  ]},
  {id:'em_scenekunst_scenografi_lys_lyd_kostyme',chapter:'dramaturgi-utover-regi-scenisk-form',sources:['src_ntnu_learning','src_khio_theatre'],title:'Scenografi, lys, lyd, kostyme og sceneteknikk',paragraphs:[
    'Scenisk form består av systemer som virker i tid: rom, materialer, kostyme, lys, lyd, video og maskineri endrer hva som kan sees, høres og gjøres. NTNU beskriver egne teaterlokaler og oppdatert sceneteknisk og digitalt utstyr som del av læringsmiljøet, men teknisk kapasitet er bare en forutsetning. Analysen må følge konkrete cues og romlige endringer og spørre hvilken dramaturgisk funksjon de får i den bestemte forestillingen.',
    'Dokumentasjonsfoto er nyttig for form, men kan fordreie skala, kontrast og publikumsblikk; lydopptak kan miste romlig plassering; en teknisk rider beskriver planlagt behov, ikke nødvendigvis alle faktiske valg. Derfor bør scenografisk og sceneteknisk analyse triangulere flere kildetyper. Når mulig sammenholdes plan, opptak og observasjon slik at forskjellen mellom designintensjon, realisert cue og dokumentasjonsmediets begrensning blir synlig.',
    'Teknisk kompleksitet må ikke forveksles med estetisk kvalitet. En enkel lyspære kan ha stor dramaturgisk betydning, mens et avansert system kan være funksjonelt men lite fremtredende i komposisjonen. Nabogrensen mot Film & TV går ved verkets primære situasjon: skjerminnhold kan inngå i scenekunsten, men analysen her undersøker hvordan mediet fungerer i den levende, samtidige fremføringssituasjonen, ikke en fullstendig filmfaglig analyse av skjermverket.'
  ]},
  {id:'em_scenekunst_dans_koreografi',chapter:'dans-musikkteater-komikk-hybridformer',sources:['src_khio_dance','src_khio_choreo'],title:'Dans, koreografi og kroppslig kunnskap',paragraphs:[
    'Koreografisk analyse beskriver hvordan bevegelse organiseres i rom og tid gjennom retning, nivå, varighet, kraft, repetisjon, relasjon og komposisjon. KHiOs master i dans kombinerer bevegelsespraksis med utøvende og skapende metode, mens koreografimasteren kobler kunstnerisk praksis til metodisk og begrepsmessig refleksjon. Det gir et faglig grunnlag for å skille den observerbare bevegelsen fra tolkningen av hva bevegelsen kulturelt eller emosjonelt betyr.',
    'Kroppslig kunnskap kan være taus eller vanskelig å oversette fullt ut til verbal beskrivelse, men det fritar ikke analysen fra presisjon. Feltnotat, video, koreografisk notasjon og utøverrefleksjon kan belyse ulike sider av samme praksis. Opptakets kameravinkel må samtidig behandles som en begrensning: det kan gjøre enkelte relasjoner tydelige og andre usynlige, og kan ikke gjenskape publikums romlige erfaring.',
    'Dans må også plasseres historisk og sosialt uten at kontekst erstatter formanalyse. KHiOs danseprogram fremhever estetiske, dansehistoriske, politiske, etiske og sosiale perspektiver. En sterk tolkning viser derfor først hva kroppen og komposisjonen gjør, deretter hvordan bestemte tradisjoner, institusjoner eller maktforhold kan informere lesningen. Den unngår å gjøre utøverens identitet til en automatisk forklaring på hvert scenisk tegn.'
  ]},
  {id:'em_scenekunst_musikal_musikkteater',chapter:'dans-musikkteater-komikk-hybridformer',sources:['src_khio_theatre','src_ntnu_learning'],title:'Musikal og musikkteater',paragraphs:[
    'Musikkteater organiserer sang, instrumental musikk, tekst, skuespill, bevegelse og visuell form i samme live-forløp. Scenekunstanalysen spør hvordan disse uttrykkene integreres dramaturgisk: om et musikalsk nummer stopper, kommenterer eller driver handlingen; hvordan overgangen mellom tale og sang markeres; og hvordan utøver, orkester eller avspilling plasseres i rommet. Den musikalske harmonikken eller komposisjonsteknikken i seg selv tilhører nabofaget Musikk når den krever selvstendig musikkvitenskapelig analyse.',
    'KHiOs teaterutdanning og NTNUs praktisk-teoretiske drama- og teaterløp understreker at scenisk arbeid er samarbeidsbasert. I musikkteater gjør dette kreditering særlig viktig fordi regissør, koreograf, musikalsk leder, komponist, librettist, designer og utøvere kan ha ulike ansvarsområder. Sluttforestillingen viser integrasjonen, men produksjons- og prøvekilder trengs dersom analysen skal hevde hvem som bestemte en bestemt overgang eller fortolkningsløsning.',
    'Et nummer bør heller ikke vurderes som vellykket bare fordi publikum applauderer. Applaus dokumenterer en hendelse i salen, men kan ha konvensjonelle, sosiale og situasjonelle årsaker. Resepsjonsanalyse må bruke flere spor dersom den skal si noe om opplevelse eller vurdering. Slik holdes musikkteaterets live-integrasjon som Scenekunstens kjerne samtidig som musikalsk detaljanalyse og publikumspsykologi ikke absorberes ukritisk.'
  ]},
  {id:'em_scenekunst_revy_standup_impro',chapter:'dans-musikkteater-komikk-hybridformer',sources:['src_ntnu_learning','src_ntnu_bachelor'],title:'Revy, standup og improvisasjon',paragraphs:[
    'Revy, standup og improvisasjon er forskjellige live-formater selv når alle bruker komikk og direkte publikumskontakt. Revy kan være nummerbasert og sterkt skrevet, standup organiseres ofte rundt én utøvers taleposisjon, mens improvisasjon kan gjøre regler for spontan utvikling til selve formatet. NTNUs vekt på nyere dramaturgiske og interaktive former gir grunn til å analysere graden av forhåndsstruktur konkret fremfor å kalle alt som virker spontant «impro».',
    'Timing i live-komikk oppstår i relasjonen mellom materiale, utøver og respons. En pause etter latter kan observeres, men det er en egen påstand å si at publikum «styrte» forestillingen. For å dokumentere påvirkning bør analysen sammenligne sekvenser, eventuelle flere forestillinger eller uttalte formatregler og vise hvilke valg som faktisk endret seg. Dermed skilles respons som lydhendelse fra kausal effekt på dramaturgien.',
    'Aktualitet er særlig viktig i revy og standup fordi referanser kan miste eller endre betydning raskt. Historisk analyse bør bevare dato, sted og relevant offentlig kontekst og unngå å lese eldre materiale bare gjennom dagens normer. Samtidig kan satire analyseres formelt gjennom mål, perspektiv, overdrivelse og reversering før en vurderer sosial eller politisk effekt, som krever bredere resepsjons- og kontekstdata.'
  ]},
  {id:'em_scenekunst_hybrid_intermedial_scenekunst',chapter:'dans-musikkteater-komikk-hybridformer',sources:['src_ntnu_learning','src_khio_perf'],title:'Hybrid og intermedial scenekunst',paragraphs:[
    'Hybrid scenekunst kombinerer praksiser uten at grensene mellom fag automatisk forsvinner. NTNUs studium fremhever nyere interaktive former, og KHiOs performance-teori henter analytiske grep fra estetikk, kulturstudier og samfunnsvitenskap. En intermedial analyse bør derfor beskrive hva hvert medium faktisk gjør i tid og rom, hvordan overganger organiseres, og hvilken del av verket som avhenger av samtidig kroppslig eller publikumsnær fremføring.',
    'Liveness blir komplisert når strømmet video, forhåndsinnspilt lyd, sensorer eller fjernpublikum inngår. Teknologien gjør ikke verket mindre scenekunst dersom den primære kunstneriske situasjonen fortsatt organiseres som levende eller samtidig fremføring. Omvendt blir et selvstendig skjermverk ikke Scenekunst bare fordi det vises på en scene. Nabogrensen mot Film & TV må derfor begrunnes gjennom verkets primære praksis og publikumsrelasjon.',
    'Interaktiv teknologi kan registrere input uten å gi publikum reell innflytelse på forløpet. Analysen bør kartlegge hvilke handlinger systemet aksepterer, hvilke konsekvenser de faktisk har og hvilke valg som fortsatt er låst av kunstner eller programvare. Det gjør det mulig å skille grensesnitt, dramaturgisk respons og deltakermakt og hindrer at teknologisk nyhet brukes som synonym for estetisk eller demokratisk innovasjon.'
  ]},
  {id:'em_scenekunst_publikum_fjerde_vegg',chapter:'publikum-resepsjon-deltakelse-etikk',sources:['src_ntnu_learning','src_ntnu_bachelor'],title:'Publikum, henvendelse og den fjerde veggen',paragraphs:[
    'Den fjerde veggen er en analytisk modell for hvordan en forestilling organiserer grensen mellom scene og sal. Direkte blikk, tiltale, fysisk passasje gjennom publikum eller invitasjon til handling kan dokumenteres som sceniske grep, men fravær av slike grep betyr ikke at publikum er uten betydning. NTNUs produksjoner for ulike publikumsgrupper viser hvorfor publikumsposisjonen må analyseres som del av den konkrete fremføringssituasjonen.',
    'Henvendelse har grader. En skuespiller kan tale mot salen uten å vente på svar, en improvisatør kan bruke et muntlig forslag, og et immersivt verk kan kreve fysisk forflytning. Disse situasjonene bør ikke samles under ett ord som «deltakelse». Forestillingsanalysen må beskrive hva publikum faktisk kan gjøre, når handlingen blir registrert og hvordan forløpet eventuelt endres.',
    'Observasjon av publikum gir heller ikke direkte tilgang til indre opplevelse. Latter, stillhet, applaus, avgang eller bevegelse er registrerbare hendelser; interesse, identifikasjon eller krenkelse er fortolkninger som krever andre data dersom de skal generaliseres. Denne avgrensningen gjør det mulig å analysere scene–sal-relasjonen presist uten å late som forskeren kan lese et helt publikums mentale tilstand.'
  ]},
  {id:'em_scenekunst_performance_teori_liveness',chapter:'publikum-resepsjon-deltakelse-etikk',sources:['src_khio_perf','src_khio_dance'],title:'Performance-teori, nærvær og liveness',paragraphs:[
    'Performance-teori gir begreper for å undersøke handling, kropp, gjentakelse, mediering og offentlig situasjon på tvers av etablerte sjangre. KHiOs performance-teori kobler scenekunst til estetikk, kulturstudier og samfunnsvitenskapelige perspektiver, mens danseprogrammet plasserer utøvende praksis i historisk, politisk, etisk og sosial kontekst. Teori skal derfor brukes som eksplisitt analytisk linse, ikke som et erstatningsspråk for det som faktisk skjer i forestillingen.',
    'Liveness bør behandles som et forhold mellom samtidighet, mediering og forventning, ikke som en mystisk egenskap som all scenekunst automatisk har i samme grad. En forestilling kan kombinere live-kropp, opptak og fjernforbindelse; analysen må vise hvilke elementer som er samtidige med publikum og hvilke som er lagret eller automatisert. Slik kan nærvær diskuteres uten å gjøre «live» til et kvalitetsstempel.',
    'Teoretiske perspektiver kan også konkurrere. En analyse av representasjon kan fremheve makt og kategorisering, mens en fenomenologisk lesning kan konsentrere seg om kroppslig erfaring. Universitetstilpasset arbeid bør gjøre valget synlig, forklare hva perspektivet gjør mulig å se og teste om materialet faktisk støtter tolkningen. Ett teoribegrep er ikke evidens i seg selv; det organiserer spørsmål som fortsatt må besvares med kilder og observasjon.'
  ]},
  {id:'em_scenekunst_resepsjon_kritikk_publikumsdata',chapter:'publikum-resepsjon-deltakelse-etikk',sources:['src_kult_stats','src_khio_perf'],title:'Resepsjon, kritikk og publikumsdata',paragraphs:[
    'Resepsjonsanalyse må skille datatyper. Kulturdirektoratets statistikk kan dokumentere besøk, arrangement, billettstatus og økonomiske størrelser for rapporterende institusjoner, mens en anmeldelse er én kritikers argumenterte vurdering og et intervju eller spørreskjema kan gi deltakernes egne beskrivelser. Ingen av disse kildene er alene et mål på «publikums mening», og de bør ikke summeres som om de målte det samme.',
    'Besøkstall måler oppmøte, ikke opplevelse eller kunstnerisk kvalitet. Selv en tydelig endring over tid kan ha flere forklaringer: kapasitet, antall forestillinger, pris, turné, repertoar, registreringspraksis eller eksterne forhold. Statistisk argumentasjon skal derfor oppgi populasjon, periode og definisjon og være forsiktig med kausalitet. Kulturdirektoratets egen avgrensning til bestemte rapporterende virksomheter må følge analysen.',
    'Kritikk kan studeres som offentlig diskurs uten å gjøres representativ for alle publikummere. KHiOs performance-teori bruker flere kritiske perspektiver, og resepsjonsanalysen kan undersøke hvilke estetiske og normative kriterier anmeldere aktiverer, hva de sammenligner med og hvordan begreper endrer seg over tid. Et robust resultat viser mønstre i et definert korpus og beholder forskjellen mellom kritikerposisjon, publikumsdata og forskerens egen vurdering.'
  ]},
  {id:'em_scenekunst_deltakende_immersiv_scenekunst',chapter:'publikum-resepsjon-deltakelse-etikk',sources:['src_ntnu_learning','src_khio_choreo','src_lovdata_uu'],title:'Deltakende og immersiv scenekunst',paragraphs:[
    'Deltakende scenekunst bør analyseres gjennom konkret handlingsrom. NTNUs vekt på interaktive former viser at interaksjon er et faglig felt, men et verk kan invitere til valg som er symbolske, reversible, obligatoriske eller faktisk forløpsendrende. Analysen kartlegger derfor instruksjon, valgmuligheter, mulighet til å avstå og konsekvenser av deltakernes handlinger før den vurderer hvor stor medvirkning formatet gir.',
    'Immersjon er heller ikke det samme som samtykke. En deltaker kan være fysisk omsluttet av en forestilling og samtidig ha uklare muligheter til å trekke seg, forstå berøring eller forutse sosial eksponering. KHiOs koreografimaster løfter yrkesetiske problemstillinger, og deltakelsesanalysen bør registrere informasjon før forestillingen, opt-out-muligheter, personalets håndtering og maktasymmetrier. Etisk kvalitet må vurderes i situasjonen, ikke bare i kunstnerens intensjon.',
    'Tilgang påvirker hvem som faktisk kan delta. Lovens universell-utformingsplikt gjør fysiske og digitale barrierer til mer enn en valgfri estetisk detalj for virksomheter rettet mot allmennheten. I et immersivt verk kan rute, lysnivå, lydinformasjon, språk, ståtid og digitalt grensesnitt være del av både estetikk og tilgang. Analysen må beskrive konkrete barrierer og tilrettelegginger uten å anta at én løsning fungerer likt for alle.'
  ]},
  {id:'em_scenekunst_etikk_tilgjengelighet_representasjon',chapter:'publikum-resepsjon-deltakelse-etikk',sources:['src_lovdata_uu','src_khio_perf','src_khio_dance'],title:'Etikk, representasjon og tilgjengelighet',paragraphs:[
    'Universell utforming gir et rettslig minimumsspråk for tilgang: Lovdata gjengir plikten for offentlige og private virksomheter rettet mot allmennheten til å utforme hovedløsninger slik at de kan brukes av flest mulig, med en konkret vurdering av blant annet barrierereduksjon, kostnad, ressurser, sikkerhet og vern. Scenekunstanalyse må derfor undersøke inngang, sikt, bevegelse, informasjon og digitale løsninger som faktiske forhold, ikke nøye seg med en generell påstand om at en arena er «inkluderende».',
    'Representasjon krever mer enn telling. KHiOs performance-teori inkluderer blant annet interseksjonelle, postkoloniale, queer- og kritiske raseteoretiske perspektiver, mens danseprogrammet kobler praksis til politisk, etisk og sosial kontekst. Analysen bør spørre hvem som får tale og handle, hvordan kategorier bygges scenisk, hvilke maktrelasjoner produksjonen inngår i og hvilke kilder som bærer tolkningen. Identiteten til en utøver er ikke alene bevis for verkets politiske betydning.',
    'Etikk gjelder også arbeids- og publikumsrelasjoner: samtykke, kreditering, maktasymmetri, tilgjengelighet og risiko kan være del av produksjonsformen. Normativ vurdering må skilles fra empirisk observasjon, men den kan ikke utelates når et verk faktisk fordeler risiko eller adgang ulikt. En substansiell vurdering navngir berørte grupper, konkret praksis, relevant rettighet eller norm, mulige konflikter og hvilken evidens som finnes, fremfor å avslutte med generelle formuleringer om respekt og mangfold.'
  ]}
];

