const canonicalIds=canonicalEmners.map(e=>e.emne_id);
assert(TOPICS.length===20&&new Set(TOPICS.map(t=>t.id)).size===20,'Materializer må ha 20 unike emner');
assert(canonicalIds.length===20&&canonicalIds.every(id=>TOPICS.some(t=>t.id===id)),'Materializer matcher ikke canonical emner');
const fagkartOwners=Object.fromEntries(fagkart.categories.flatMap(c=>c.emne_ids.map(id=>[id,c.id])));
for(const t of TOPICS)assert(fagkartOwners[t.id]===CHAPTERS.find(c=>c.id===t.chapter)?.domain,`Kapittel-eierskap bryter fagkartet: ${t.id}`);

let claimCounter=1; const chapterRecords=[];
for(const chapter of CHAPTERS){
  const topics=TOPICS.filter(t=>t.chapter===chapter.id); const chapterDir=`data/fagverk/scenekunst/${chapter.id}`; const modulePath=`${chapterDir}/01-fulltekst.json`; const claimsPath=`${chapterDir}/claims.json`; const briefPath=`${chapterDir}/brief.json`; const rootPath=`data/fagverk/scenekunst/${chapter.id}.json`; const usedSourceIds=new Set(); const claims=[];
  const sections=topics.map((topic,topicIndex)=>{const emne=canonicalEmners.find(e=>e.emne_id===topic.id); const paragraphClaimIds=[]; topic.sources.forEach(id=>assert(sourceById.has(id),`Ukjent kilde ${id}`));topic.sources.forEach(id=>usedSourceIds.add(id)); for(let i=0;i<topic.paragraphs.length;i++){const cid=`scn-${String(claimCounter++).padStart(3,'0')}`;paragraphClaimIds.push([cid]);claims.push({id:cid,claim:topic.paragraphs[i],source_ids:[...topic.sources],status:'verified',evidence_note:`Avsnitt ${i+1} i ${topic.id} bygger på de navngitte kildenes konkrete studie-, sektor-, arkiv- eller rettslige opplysninger og avgrenser slutningen metodisk.`,used_in:[`${chapter.id}-emne-${topicIndex+1}`]});}
    return{id:`${chapter.id}-emne-${topicIndex+1}`,emne_id:topic.id,title:topic.title,method_ids:emne.method_ids,paragraphs:topic.paragraphs,paragraphClaimIds,keyPoints:[emne.definition,emne.why_it_matters],keyPointClaimIds:[[paragraphClaimIds[0][0]],[paragraphClaimIds[1][0]]]};});
  const methodIds=[...new Set(topics.flatMap(t=>canonicalEmners.find(e=>e.emne_id===t.id).method_ids))];
  const root={schema:'history_go_fagverk_chapter_v1',version:'1.0.0',subject:'scenekunst',subject_id:'scenekunst',id:chapter.id,chapter_id:chapter.id,primary_domain_id:chapter.domain,editorialStatus:'chapter_ready',claimTraceRequired:true,emne_ids:topics.map(t=>t.id),method_ids:methodIds,title:chapter.title,subtitle:chapter.subtitle,lead:`Kapittelet undersøker ${chapter.title.toLowerCase()} gjennom canonicale emner, eksplisitte metodebegrensninger og etterprøvbare kilder. Hvert fagavsnitt har paragraph-to-claim-spor, og nabofag brukes bare der de forklarer den levende fremføringssituasjonen.`,learningObjectives:topics.map(t=>`analysere ${t.title.toLowerCase()} med eksplisitt skille mellom observasjon, kilde og fortolkning`),diagnosticQuestions:topics.slice(0,3).map(t=>({question:`Hva må dokumenteres før du trekker en sterk konklusjon om ${t.title.toLowerCase()}?`,answer:'Identifiser kildetype og observasjon, bruk relevant canonical metode, og avgrens konklusjonen til det materialet faktisk kan bære.'})),neighborBoundaries:readiness.neighbor_boundaries,moduleFiles:[modulePath],briefFile:briefPath,claimsFile:claimsPath};
  const module={schema:'history_go_fagverk_chapter_module_v1',version:'1.0.0',subject_id:'scenekunst',chapter_id:chapter.id,sections};
  const sources=[...usedSourceIds].map(id=>sourceById.get(id)); const claimsDoc={schema:'history_go_fagverk_chapter_claims_v1',version:'1.0.0',subject_id:'scenekunst',chapter_id:chapter.id,sources,claims};
  const brief={schema:'history_go_fagverk_chapter_brief_v1',version:'1.0.0',subject_id:'scenekunst',chapter_id:chapter.id,status:'fulltext_materialized',scope:chapter.subtitle,canonical_emne_ids:topics.map(t=>t.id),canonical_method_ids:methodIds,source_strategy:'Autoritative universitets-, sektor-, arkiv- og rettskilder med konkrete locators; institusjonelle selvbeskrivelser brukes som kilder til mandat/studieinnhold, ikke som automatisk bevis for effekt eller kvalitet.',limitations:['Et opptak erstatter ikke live-situasjonen.','Arkivfravær er ikke automatisk bevis for historisk fravær.','Besøkstall og økonomi måler ikke kunstnerisk kvalitet eller publikumsopplevelse.','Observasjon av handling beviser ikke kunstnerisk intensjon.']};
  writeJson(rootPath,root);writeJson(modulePath,module);writeJson(claimsPath,claimsDoc);writeJson(briefPath,brief);chapterRecords.push({id:chapter.id,title:chapter.title,subtitle:chapter.subtitle,file:rootPath,primary_domain_id:chapter.domain,chapter_role:'core',emne_ids:topics.map(t=>t.id),claimsFile:claimsPath,briefFile:briefPath});
}
const usedMethods=new Set(chapterRecords.flatMap(r=>readJson(r.file).method_ids)); const canonicalMethods=methodsDoc.methods.map(m=>m.method_id); assert(canonicalMethods.every(id=>usedMethods.has(id)),`Ikke alle 14 canonicale metoder brukes: ${canonicalMethods.filter(id=>!usedMethods.has(id)).join(', ')}`);

